package com.vraj.khetihisab.data.dao

import androidx.room.Dao
import androidx.room.Query
import androidx.room.Transaction
import androidx.room.Upsert
import com.vraj.khetihisab.data.entity.PersonProfileEntity
import com.vraj.khetihisab.data.entity.ProfileRole
import kotlinx.coroutines.flow.Flow

/**
 * Owner + two manager profiles. `role` is unique, so there is at most one row per role.
 *
 * [upsert] resolves the existing row by role first. A plain @Upsert keyed on the autogenerated id
 * would hit the unique(role) constraint, fall back to UPDATE ... WHERE id=0 and silently drop the edit.
 */
@Dao
abstract class ProfileDao {
    @Query("SELECT * FROM person_profile ORDER BY CASE role WHEN 'OWNER' THEN 0 WHEN 'MANAGER_1' THEN 1 ELSE 2 END")
    abstract fun all(): Flow<List<PersonProfileEntity>>

    @Query("SELECT * FROM person_profile WHERE role=:role LIMIT 1")
    abstract fun byRole(role: ProfileRole): Flow<PersonProfileEntity?>

    @Query("SELECT * FROM person_profile WHERE role=:role LIMIT 1")
    abstract suspend fun byRoleNow(role: ProfileRole): PersonProfileEntity?

    @Query("SELECT COUNT(*) FROM person_profile")
    abstract suspend fun count(): Int

    @Upsert
    protected abstract suspend fun upsertById(p: PersonProfileEntity)

    @Transaction
    open suspend fun upsert(p: PersonProfileEntity) {
        val existing = byRoleNow(p.role)
        upsertById(if (existing != null) p.copy(id = existing.id) else p)
    }

    @Query("UPDATE person_profile SET photoPath=:path, updatedAt=:now WHERE role=:role")
    abstract suspend fun updatePhoto(role: ProfileRole, path: String?, now: Long)
}
